-- Generated by scripts/build_compiled.py from src/fraudrules/rules/structuring/st-003-multi-location-cash.yaml. Do not edit.
-- ST-003 Cash deposits spread across several branches or ATMs in one day
SELECT
  'ST-003' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.customer_id = a.customer_id AND b.ts <= a.ts AND b.ts > a.ts - 86400
WHERE
  (
    a.channel IN ('cash', 'atm') AND a.direction = 'in' AND a.txn_type = 'deposit'
  )
  AND (
    b.channel IN ('cash', 'atm') AND b.direction = 'in' AND b.txn_type = 'deposit'
  )
GROUP BY
  a.id
HAVING
  (
    COUNT(DISTINCT b.location_id) >= 3 AND SUM(b.amount_cents) >= 800000
  );
